task.vi:
Hãy chỉ ra kết quả xuất ra màn hình của các đoạn chương trình sau (Gợi ý: Lập bảng biến số để lần vết):
(a)
for (int i = 1; i < 5; i++)
{
  int j = 0;
  while (j < i)
  {
    cout << j << " ";
    j++;
  }
}

(b)
int i = 0;
while (i < 5)
{
  for (int j = i; j > 1; j--)
    cout << j << " ";
  cout << "****" << endl;
  i++;
}

(c)
int i = 5;
while (i >= 1)
{
  int num = 1;
  for (int j = 1; j <= i; j++)
  {
    cout << num << "xxx";
    num *= 2;
  }
  cout << endl;
  i--;
}

(d)
int i = 1;
do
{
  int num = 1;
  for (int j = 1; j <= i; j++)
  {
    cout << num << "G";
    num += 2;
  }
  cout << endl;
  i++;
} while (i <= 5);

