example.code:
#include <iostream>

int main() {
    // Chuyển đổi tương đương Check Point 5.18: while sang for
    int sum_while = 0;
    int i_w = 1;
    while (sum_while < 20) {
        sum_while += i_w;
        i_w++;
    }

    // Tương đương chuyển sang for loop
    int sum_for = 0;
    int i_f = 1;
    for (; sum_for < 20; i_f++) {
        sum_for += i_f;
    }

    std::cout << "While sum: " << sum_while << ", next i: " << i_w << "\n";
    std::cout << "For sum:   " << sum_for << ", next i: " << i_f << "\n";

    return 0;
}

