#include <iostream>
#include <iomanip>

int main() {
    std::cout << "Multiplication Table (1-4)\n";
    std::cout << "-------------------------\n";
    std::cout << "  | ";
    for (int j = 1; j <= 4; j++) {
        std::cout << std::setw(3) << j;
    }
    std::cout << "\n";

    for (int i = 1; i <= 4; i++) {
        std::cout << i << " | ";
        for (int j = 1; j <= 4; j++) {
            std::cout << std::setw(3) << i * j;
        }
        std::cout << "\n";
    }
    return 0;
}

